// Remaining locales have full source-key coverage; missing entries intentionally use English until reviewed translation ships.
export type Catalog = Record<MessageKey, string>;
export const catalogs: Record<Locale, Catalog> = Object.fromEntries(localeOptions.map(([locale]) => {
  const row = rows[locale];
  const values: Record<string, string> = {};
  messageKeys.forEach((key, index) => { values[key] = row?.[index] || key; });
  actionKeys.forEach((key, index) => { values[key] = actionRows[locale]?.[index] || key; });
  phraseKeys.forEach((key, index) => { values[key] = phraseRows[locale]?.[index] || key; });
  lessonContentKeys.forEach((key, index) => { values[key] = lessonContentRows[locale]?.[index] || englishLessonContent[index]; });
  lessonUiKeys.forEach((key, index) => { values[key] = lessonUiRows[locale]?.[index] || key; });
  dashboardToolKeys.forEach((key, index) => { values[key] = dashboardToolRowsByLocale[locale]?.[index] || key; });
  appMetadataKeys.forEach((key) => { values[key] = appMetadataRows[locale] || appMetadataRows.en; });
  return [locale, values];
})) as Record<Locale, Catalog>;

export function translate(locale: Locale, key: string, values?: Record<string, string | number>): string {
  const result = (catalogs[locale] as Record<string, string>)[key] ?? key;
  return result.replace(/\{(\w+)\}/g, (_, name: string) => String(values?.[name] ?? `{${name}}`));
}
export function translatePlural(locale: Locale, count: number, forms: Partial<Record<Intl.LDMLPluralRule, string>> & { other: string }, values: Record<string, string | number> = {}): string {
  const category = new Intl.PluralRules(locale).select(count);
  const template = forms[category] ?? forms.other;
  return template.replace(/\{(\w+)\}/g, (_, name: string) => String(values[name] ?? (name === "count" ? count : `{${name}}`)));
}

export function numberingSystemFor(locale: Locale): string | undefined {
  if (locale === "ar") return "arab";
  if (locale === "fa" || locale === "ur") return "arabext";
  if (locale === "bn") return "beng";
  if (locale === "hi") return "deva";
  if (locale === "th") return "thai";
  return undefined;
}

